import React, { Children } from 'react';
import { Container } from '@fiverr-private/layout_components';
import { TabPanelsProps } from '../types';
import { useTabContext } from '../TabContext';
import { renderTabPanelChild } from './helpers';

const TabPanels = ({
  children,
  renderChildren = renderTabPanelChild,
  dataTrackTag = 'tab_panels',
  ...props
}: TabPanelsProps) => {
  const context = useTabContext();

  return (
    <Container dataTrackTag={dataTrackTag} {...props}>
      {Children.map(Children.toArray(children), renderChildren(context))}
    </Container>
  );
};

TabPanels.displayName = 'TabPanels';

export default TabPanels;
